function probeAtlasMarkerSemantics(params: any): any {
    const pkg = resolvePackage(params || {});
    const mode = String((params && params.mode) || "observe");
    const targetName = params && params.itemName ? String(params.itemName) : "";
    const snapshot = (): any[] => {
        const persisted = persistedAtlasByItemId(pkg);
        const rows: any[] = [];
        for (let i = 0; i < pkg.items.Count; i++) {
            const item = pkg.items.get_Item(i);
            if (!item || item.type !== FairyEditor.FPackageItemType.IMAGE) continue;
            if (targetName && String(item.name) !== targetName) continue;
            rows.push({
                id: String(item.id), name: String(item.name),
                width: Number(item.width) || 0, height: Number(item.height) || 0,
                supportAtlas: item.supportAtlas !== false,
                folderAtlasInMemory: String(item.folderAtlas || ""),
                folderAtlasOnDisk: String(persisted[String(item.id)] || "")
            });
        }
        return rows;
    };
    const result: any = { probe: "atlas-marker-semantics", editorVersion: "6.1.4",
        package: String(pkg.name), mode: mode, targetItemName: targetName || "(全部图片)",
        before: snapshot() };
    if (mode === "save-control") { pkg.Save(); App.project.Save(); result.after = snapshot(); }
    else if (mode === "clear") {
        for (let i = 0; i < pkg.items.Count; i++) {
            const item = pkg.items.get_Item(i);
            if (!item || item.type !== FairyEditor.FPackageItemType.IMAGE) continue;
            if (targetName && String(item.name) !== targetName) continue;
            item.folderAtlas = ""; item.SetChanged();
        }
        pkg.Save(); App.project.Save(); result.after = snapshot();
    }
    else if (mode === "assign") {
        const value = String((params && params.value) || "");
        for (let i = 0; i < pkg.items.Count; i++) {
            const item = pkg.items.get_Item(i);
            if (!item || item.type !== FairyEditor.FPackageItemType.IMAGE) continue;
            if (targetName && String(item.name) !== targetName) continue;
            item.folderAtlas = value; item.SetChanged();
        }
        pkg.Save(); App.project.Save(); result.after = snapshot();
    }
    else if (mode !== "observe") throw new Error("未知的探针模式：" + mode);
    return result;
}
